export function calculatePrimeFactors(n: number): number[] {
  const factors: number[] = [];

  // Handle edge cases for non-positive numbers or invalid inputs
  if (n <= 1 || !Number.isInteger(n) || Number.isNaN(n) || Number.isInfinity(n)) {
    return [];
  }

  let currentNumber = n;

  // Check for factor 2 separately to allow skipping even numbers later
  while (currentNumber % 2 === 0) {
    factors.push(2);
    currentNumber /= 2;
  }

  // Check for odd factors starting from 3
  let divisor = 3;
  while (divisor * divisor <= currentNumber) {
    while (currentNumber % divisor === 0) {
      factors.push(divisor);
      currentNumber /= divisor;
    }
    divisor += 2;
  }

  // If currentNumber is greater than 1, it is a prime factor itself
  if (currentNumber > 1) {
    factors.push(currentNumber);
  }

  return factors;
}
